var a=`0073-langos`;var i=`world-0073`;var t=`HU`;var s=`eastern-europe`;var o=4;var l=90;var r={en:`Lángos`,ua:`Лангош`};var u={en:`A classic dish from Hungary, featuring whole cow milk, garlic, sour cream, emmental. A practical home-kitchen version with measured step ingredients and clear cooking methods.`,ua:`Класична страва з Угорщина. Основні складники: цільне коров'яче молоко, часник, сметана, емменталь. Домашній варіант із поетапними діями та точними кількостями продуктів.`};var g=[{en:`Mix and knead into a supple yeast dough. Cover and leave in a warm place until roughly doubled, about 65 minutes.`,ua:`Змішайте й вимісіть м’яке дріжджове тісто. Накрийте та поставте в тепле місце до збільшення об’єму приблизно вдвічі, орієнтовно на 65 хвилин.`,t:[`mixing`,`kneading`,`bulk-fermentation`],m:65,i:[[`all-purpose-flour`,470,`g`],[`whole-cow-milk`,190,`ml`],[`water`,100,`ml`],[`instant-yeast`,7,`g`],[`table-salt`,7,`g`],[`white-granulated-sugar`,10,`g`]]},{en:`Roll or press the prepared dough evenly into the desired thickness and shape.`,ua:`Розкачайте або розпластайте підготовлене тісто рівномірним шаром потрібної товщини та форми.`,t:[`pressing`,`rolling-out-dough`],m:10,i:[]},{en:`Fry shaped portions in small batches in oil heated to about 170–175°C for about 12 minutes, until golden; drain on a rack.`,ua:`Смажте сформовані вироби невеликими партіями в олії температурою приблизно 170–175°C близько 12 хвилин до золотистості; викладіть на решітку.`,t:[`deep-frying`],m:12,i:[[`sunflower-oil`,750,`ml`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`garlic`,3,`clove`],[`sour-cream`,130,`g`],[`emmental`,150,`g`]]}];var d={slug:a,id:i,country:`HU`,region:s,servings:4,minutes:90,title:r,text:u,steps:g};export{t as country,d as default,i as id,l as minutes,s as region,o as servings,a as slug,g as steps,u as text,r as title};